        matches = re.findall(r'self\.__next_f\.push\(\[\d+,\s*\"(.*)\"\s*\]\)', s.string)
        for m in matches:
            try:
                decoded = json.loads('\"' + m + '\"')
                all_chunks.append(decoded)
