                decoded = m.replace('\\\"', '\"').replace('\\\\', '\\')
                all_chunks.append(decoded)

paragraphs = []
for chunk in all_chunks:
    matches = re.findall(r'\"children\":\[\"([^\"]+)\"\]', chunk)
    for m in matches:
        if len(m) > 40:
            paragraphs.append(m)
    matches_single = re.findall(r'\"children\":\"([^\"]+)\"', chunk)
    for m in matches_single:
        if len(m) > 40 and not m.startswith('$'):
